def load_embedded(data):
    """Load a base64 PNG embedded in this file; None if Tk can't decode it."""
    try:
        return tk.PhotoImage(data=data)
    except tk.TclError:
        return None


class Game:
    def __init__(self, root):
        self.root = root
        root.title("Reflex Arena")
        root.resizable(False, False)
        # a transparent icon replaces the default feather icon
        self.icon = tk.PhotoImage(width=16, height=16)
        try:
            root.iconphoto(True, self.icon)
        except tk.TclError:
            pass
        self.bg_image = make_background()
        self.race_bg = load_embedded(RACE_BG_DATA)
        self.blitz_bg = load_embedded(BLITZ_BG_DATA)
        self.c = tk.Canvas(root, width=W, height=H, bg="#05070f", highlightthickness=0)
        self.c.pack()
        self.c.bind("<Button-1>", lambda e: self.click(e.x, e.y))
        root.bind("<space>", lambda e: self.click(None, None))
        root.bind("<Escape>", lambda e: self.to_menu())
        root.bind("1", lambda e: self.state == "menu" and self.start_race())
        root.bind("2", lambda e: self.state == "menu" and self.start_blitz())
        self.scores = load_scores()
        self.stars = [[random.uniform(0, W), random.uniform(0, 300), random.uniform(0.2, 1.5)]
                      for _ in range(110)]
        self.particles = []
        self.popups = []
        self.shake = 0.0
        self.flash = None
        self.to_menu()
        self.last = time.perf_counter()
        self.tick()

    # ---------- helpers ----------
    def to_menu(self):
        self.state = "menu"

    def burst(self, x, y, color, n=30, speed=260):
        for _ in range(n):
            a = random.uniform(0, math.tau)
            s = random.uniform(40, speed)
            self.particles.append([x, y, math.cos(a) * s, math.sin(a) * s,
                                   random.uniform(0.4, 0.9), color])

    def popup(self, x, y, text, color="#ffffff"):
        self.popups.append([x, y, text, color, 1.0])

    def record(self, key, value, lower_better):
        old = self.scores.get(key)
        better = old is None or (value < old if lower_better else value > old)
        if better:
            self.scores[key] = value
            save_scores(self.scores)
        return better

    # ---------- Race Start mode ----------
    def start_race(self):
        self.state = "race"
        self.times = []
        self.new_best = False
        self.race_round()

    def race_round(self):
        self.phase = "lights"
        self.lit = 0
        self.t0 = time.perf_counter()
        self.next_light = self.t0 + 0.8
        self.hold = random.uniform(0.6, 3.0)
        self.msg = ""

    def race_update(self, now):
        if self.phase == "lights" and now >= self.next_light:
            self.lit += 1
            self.next_light = now + 0.8
            if self.lit == 5:
                self.phase = "hold"
                self.go_at = now + self.hold
        elif self.phase == "hold" and now >= self.go_at:
            self.phase = "go"
            self.go_time = now

    def race_click(self):
        now = time.perf_counter()
        if self.phase in ("lights", "hold"):
            self.phase = "false"
            self.msg = "FALSE START!  Click to retry"
            self.shake = 0.4
        elif self.phase == "go":
            ms = int((now - self.go_time) * 1000)
            self.times.append(ms)
            self.phase = "result"
            self.flash = ["#22ff88", 0.3]
            self.burst(W / 2, 260, "#22ff88", 50)
            self.msg = "%d ms" % ms
            if len(self.times) >= ROUNDS:
                self.phase = "final"
                avg = sum(self.times) / len(self.times)
                self.new_best = self.record("race_avg", round(avg), True)
        elif self.phase in ("false", "result"):
            self.race_round()
        elif self.phase == "final":
            self.to_menu()

    def draw_race(self):
        c = self.c
        c.create_text(W / 2, 40, text="RACE START  -  round %d/%d" % (min(len(self.times) + 1, ROUNDS), ROUNDS),
                      fill="#9fb3ff", font=(FONT, 16, "bold"))
        if self.phase == "final":
            avg = sum(self.times) / len(self.times)
            c.create_text(W / 2, 130, text="RESULTS", fill="white", font=(FONT, 34, "bold"))
            for i, t in enumerate(self.times):
                bar = min(t, 600) / 600 * 420
                y = 190 + i * 38
                c.create_text(150, y, text="#%d" % (i + 1), fill="#9fb3ff", font=(FONT, 14))
                c.create_rectangle(190, y - 12, 190 + bar, y + 12, fill=self.rate_color(t), outline="")
                c.create_text(200 + bar + 10, y, text="%d ms" % t, anchor="w", fill="white", font=(FONT, 13))
            c.create_text(W / 2, 410, text="Average: %.0f ms  -  %s" % (avg, self.rating(avg)),
                          fill="#ffd54a", font=(FONT, 22, "bold"))
            best = self.scores.get("race_avg")
            tag = "NEW BEST!" if self.new_best else "Best average: %s ms" % best
            c.create_text(W / 2, 450, text=tag, fill="#22ff88" if self.new_best else "#9fb3ff", font=(FONT, 16))
            c.create_text(W / 2, 490, text="Click for menu", fill="#667", font=(FONT, 12))
            return
        # gantry with five light pairs
        c.create_rectangle(110, 90, W - 110, 330, fill="#161c33", outline="#2a3358", width=3)
        for i in range(5):
            x = 170 + i * 115
            lit = self.phase in ("lights", "hold") and i < self.lit
            col = "#ff2a2a" if lit else "#2a1216"
            for y in (150, 255):
                if lit:
                    c.create_oval(x - 46, y - 46, x + 46, y + 46, fill="#661111", outline="")
                c.create_oval(x - 36, y - 36, x + 36, y + 36, fill=col, outline="#000", width=3)
        if self.phase == "go":
            c.create_text(W / 2, 210, text="GO!", fill="#22ff88", font=(FONT, 90, "bold"))
            self.draw_green_strip()
        text = {"lights": "Get ready...", "hold": "Wait for lights to go out...",
                "go": "CLICK!", "false": self.msg, "result": self.msg}.get(self.phase, "")
        color = "#ff5555" if self.phase == "false" else "#22ff88" if self.phase in ("go", "result") else "#9fb3ff"
        c.create_text(W / 2, 400, text=text, fill=color, font=(FONT, 38 if self.phase == "result" else 24, "bold"))
        if self.phase == "result":
            c.create_text(W / 2, 450, text="Click for next round", fill="#667", font=(FONT, 13))
        if self.times:
            c.create_text(W / 2, 490, text="Previous: " + "  ".join("%dms" % t for t in self.times),
                          fill="#667", font=(FONT, 12))

    def draw_green_strip(self):
        self.c.create_rectangle(0, 0, W, 8, fill="#22ff88", outline="")
        self.c.create_rectangle(0, H - 8, W, H, fill="#22ff88", outline="")

    @staticmethod
    def rating(avg):
        return ("Superhuman!" if avg < 200 else "Lightning" if avg < 250 else "Sharp" if avg < 300
                else "Average" if avg < 380 else "Warm up your fingers")

    @staticmethod
    def rate_color(ms):
        return "#22ff88" if ms < 250 else "#ffd54a" if ms < 350 else "#ff7755"

    # ---------- Target Blitz mode ----------
    def start_blitz(self):
        self.state = "blitz"
        self.score = 0
        self.combo = 0
        self.hits = 0
        self.misses = 0
        self.rts = []
        self.end_time = time.perf_counter() + BLITZ_SECONDS
        self.over = False
        self.target = None
        self.spawn_at = time.perf_counter() + 0.6
        self.new_best = False

    def spawn_target(self, now):
        r = random.randint(30, 52)
        self.target = {"x": random.uniform(r + 20, W - r - 20), "y": random.uniform(r + 70, H - r - 20),
                       "r": r, "born": now, "life": TARGET_LIFE}

    def blitz_update(self, now):
        if self.over:
            return
        if now >= self.end_time:
            self.over = True
            self.target = None
            self.new_best = self.record("blitz_score", self.score, False)
            return
        if self.target is None and now >= self.spawn_at:
            self.spawn_target(now)
        elif self.target and now - self.target["born"] > self.target["life"]:
            self.burst(self.target["x"], self.target["y"], "#ff5555", 12, 120)
            self.popup(self.target["x"], self.target["y"], "MISSED", "#ff5555")
            self.combo = 0
            self.target = None
            self.spawn_at = now + random.uniform(0.15, 0.5)

    def blitz_click(self, x, y):
        now = time.perf_counter()
        if self.over:
            self.to_menu()
            return
        if x is None:
            return
        t = self.target
        if t and (x - t["x"]) ** 2 + (y - t["y"]) ** 2 <= t["r"] ** 2:
            rt = now - t["born"]
            self.rts.append(rt)
            self.hits += 1
            self.combo += 1
            mult = 1 + self.combo // 5
            pts = max(10, int(100 - rt * 55)) * mult
            self.score += pts
            self.burst(t["x"], t["y"], "#ffd54a")
            self.popup(t["x"], t["y"], "+%d  (%d ms)" % (pts, rt * 1000), "#ffd54a")
            self.target = None
            self.spawn_at = now + random.uniform(0.1, 0.45)
        else:
            self.misses += 1
            self.combo = 0
            self.score = max(0, self.score - 25)
            self.shake = 0.25
            self.popup(x, y, "-25", "#ff5555")

    def draw_blitz(self, now):
        c = self.c
        left = max(0, self.end_time - now)
        c.create_text(20, 25, anchor="w", text="SCORE %d" % self.score, fill="white", font=(FONT, 20, "bold"))
        c.create_text(W / 2, 25, text="x%d combo %d" % (1 + self.combo // 5, self.combo),
                      fill="#ffd54a", font=(FONT, 16, "bold"))
        c.create_text(W - 20, 25, anchor="e", text="%.1fs" % left, fill="#9fb3ff", font=(FONT, 20, "bold"))
        c.create_rectangle(0, 48, W * left / BLITZ_SECONDS, 54, fill="#4d7cff", outline="")
        t = self.target
        if t:
            frac = 1 - (now - t["born"]) / t["life"]
            r = t["r"]
            col = "#22ff88" if frac > 0.5 else "#ffd54a" if frac > 0.25 else "#ff5555"
            c.create_oval(t["x"] - r - 6, t["y"] - r - 6, t["x"] + r + 6, t["y"] + r + 6,
                          outline="#223", width=4)
            c.create_arc(t["x"] - r - 6, t["y"] - r - 6, t["x"] + r + 6, t["y"] + r + 6,
                         start=90, extent=360 * max(frac, 0), style="arc", outline=col, width=4)
            for k, f in enumerate((1.0, 0.66, 0.33)):
                rr = r * f
                c.create_oval(t["x"] - rr, t["y"] - rr, t["x"] + rr, t["y"] + rr,
                              fill="#ff3b5c" if k % 2 == 0 else "#ffffff", outline="")
        if self.over:
            c.create_rectangle(150, 110, W - 150, 410, fill="#111833", outline="#4d7cff", width=3)
            c.create_text(W / 2, 160, text="TIME'S UP", fill="white", font=(FONT, 34, "bold"))
            c.create_text(W / 2, 220, text="Score: %d" % self.score, fill="#ffd54a", font=(FONT, 30, "bold"))
            avg = sum(self.rts) / len(self.rts) * 1000 if self.rts else 0
            acc = 100 * self.hits / max(1, self.hits + self.misses)
            c.create_text(W / 2, 275, text="Hits %d   Misses %d   Accuracy %.0f%%" % (self.hits, self.misses, acc),
                          fill="#9fb3ff", font=(FONT, 15))
            c.create_text(W / 2, 305, text="Average reaction: %.0f ms" % avg, fill="#9fb3ff", font=(FONT, 15))
            best = self.scores.get("blitz_score", 0)
            c.create_text(W / 2, 350, text="NEW HIGH SCORE!" if self.new_best else "High score: %d" % best,
                          fill="#22ff88" if self.new_best else "#9fb3ff", font=(FONT, 18, "bold"))
            c.create_text(W / 2, 385, text="Click for menu", fill="#667", font=(FONT, 12))

    # ---------- menu ----------
    def draw_menu(self, now):
        c = self.c
        pulse = 1 + 0.04 * math.sin(now * 3)
        c.create_text(W / 2, 100, text="REFLEX ARENA", fill="#4d7cff", font=(FONT, int(54 * pulse), "bold"))
        c.create_text(W / 2, 150, text="How fast are you really?", fill="#9fb3ff", font=(FONT, 16, "italic"))
        for i, (label, sub, key) in enumerate((
                ("1  -  Race Start", "React when the lights go out. Best avg: %s ms" % self.scores.get("race_avg", "-"), "race"),
                ("2  -  Target Blitz", "30s of shrinking targets. High score: %s" % self.scores.get("blitz_score", "-"), "blitz"))):
            y = 230 + i * 105
            c.create_rectangle(190, y - 40, W - 190, y + 40, fill="#161c33", outline="#4d7cff", width=2)
            c.create_text(W / 2, y - 12, text=label, fill="white", font=(FONT, 22, "bold"))
            c.create_text(W / 2, y + 20, text=sub, fill="#9fb3ff", font=(FONT, 12))
        c.create_text(W / 2, 480, text="Click a mode or press 1 / 2   -   SPACE or click to react   -   ESC for menu",
                      fill="#667", font=(FONT, 11))

    def menu_click(self, x, y):
        if x is None:
            return
        if 190 <= x <= W - 190:
            if 190 <= y <= 270:
                self.start_race()
            elif 295 <= y <= 375:
                self.start_blitz()

    # ---------- dispatch / loop ----------
    def click(self, x, y):
        if self.state == "menu":
            self.menu_click(x, y)
        elif self.state == "race":
            self.race_click()
        elif self.state == "blitz":
            self.blitz_click(x, y)

    def tick(self):
        now = time.perf_counter()
        dt = min(now - self.last, 0.05)
        self.last = now
        if self.state == "race":
            self.race_update(now)
        elif self.state == "blitz":
            self.blitz_update(now)
        for s in self.stars:
            s[0] = (s[0] - s[2] * 20 * dt) % W
        for p in self.particles:
            p[0] += p[2] * dt
            p[1] += p[3] * dt
            p[3] += 400 * dt
            p[4] -= dt
        self.particles = [p for p in self.particles if p[4] > 0]
        for p in self.popups:
            p[1] -= 40 * dt
            p[4] -= dt * 1.2
        self.popups = [p for p in self.popups if p[4] > 0]
        self.shake = max(0, self.shake - dt)
        self.draw(now)
        self.root.after(16, self.tick)

    def draw(self, now):
        c = self.c
        c.delete("all")
        custom = {"race": self.race_bg, "blitz": self.blitz_bg}.get(self.state)
        c.create_image(0, 0, image=custom or self.bg_image, anchor="nw")
        for x, y, z in ([] if custom else self.stars):
            tw = 0.6 + 0.4 * math.sin(now * 2 + x)
            g = int((90 + z * 100) * tw)
            c.create_oval(x, y, x + z * 1.5, y + z * 1.5, fill="#%02x%02x%02x" % (g, g, min(255, g + 40)), outline="")
        if self.flash:
            self.flash[1] -= 0.016
            if self.flash[1] <= 0:
                self.flash = None
            else:
                c.create_rectangle(0, 0, W, H, fill="#22ff88", stipple="gray25", outline="")
        if self.state == "menu":
            self.draw_menu(now)
        elif self.state == "race":
            self.draw_race()
        else:
            self.draw_blitz(now)
        for x, y, vx, vy, life, col in self.particles:
            r = max(1, life * 6)
            c.create_oval(x - r, y - r, x + r, y + r, fill=col, outline="")
        for x, y, text, col, a in self.popups:
            c.create_text(x, y, text=text, fill=col, font=(FONT, 16, "bold"))
        if self.shake > 0:
            dx, dy = random.randint(-6, 6), random.randint(-6, 6)
            for item in c.find_all()[1:]:
                c.move(item, dx, dy)


if __name__ == "__main__":
    root = tk.Tk()
    Game(root)
    root.mainloop()
